class Solution {
    public int earliestBouquetDay(int[] bloom, int bouquets, int size) {
        if ((long) bouquets * size > bloom.length) return -1;
        int[] days = Arrays.stream(bloom).distinct().sorted().toArray();
        for (int day : days) if (count(bloom, day, size) >= bouquets) return day;
        return -1;
    }

    private int count(int[] bloom, int day, int size) {
        int made = 0, run = 0;
        for (int b : bloom) {
            run = b <= day ? run + 1 : 0;
            if (run == size) { made++; run = 0; }
        }
        return made;
    }
}

