static int countBouquets(const int* bloom, int n, int day, int size) {
    int made = 0, run = 0;
    for (int i = 0; i < n; i++) {
        run = bloom[i] <= day ? run + 1 : 0;
        if (run == size) { made++; run = 0; }
    }
    return made;
}

static int cmpInt(const void* a, const void* b) {
    int p = *(const int*) a, q = *(const int*) b;
    return (p > q) - (p < q);
}

int earliestBouquetDay(int* bloom, int bloomSize, int bouquets, int size) {
    if ((long long) bouquets * size > bloomSize) return -1;
    int* days = malloc(bloomSize * sizeof(int));
    memcpy(days, bloom, bloomSize * sizeof(int));
    qsort(days, bloomSize, sizeof(int), cmpInt);
    int answer = -1;
    for (int i = 0; i < bloomSize && answer < 0; i++) {
        if (i > 0 && days[i] == days[i - 1]) continue;
        if (countBouquets(bloom, bloomSize, days[i], size) >= bouquets) answer = days[i];
    }
    free(days);
    return answer;
}

