class Solution {
    public int earliestBouquetDay(int[] bloom, int bouquets, int size) {
        if ((long) bouquets * size > bloom.length) return -1;
        int lo = Integer.MAX_VALUE, hi = 0;
        for (int b : bloom) { lo = Math.min(lo, b); hi = Math.max(hi, b); }
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (count(bloom, mid, size) >= bouquets) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    private int count(int[] bloom, int day, int size) {
        int made = 0, run = 0;
        for (int b : bloom) {
            run = b <= day ? run + 1 : 0;
            if (run == size) { made++; run = 0; }
        }
        return made;
    }
}

