    if ((long long) bouquets * size > bloomSize) return -1;
    int lo = bloom[0], hi = bloom[0];
    for (int i = 1; i < bloomSize; i++) { if (bloom[i] < lo) lo = bloom[i]; if (bloom[i] > hi) hi = bloom[i]; }
